'use strict';
// Documents 14-24.
const H = require('./helpers.js');
const { CO, CO_UP, FORMED, DEFILE, EIN, RA, ADDR, TALENT_DATE, AUTH_UNITS, RESERVE, FOUNDERS, BROCK, CLASS_A, CLASS_B, OUTSTANDING, A_TOTAL_PRICE, FMV_TOTAL, THRESHOLD, CEO, CTO, JGN_MEMBERS, N_FOUNDERS, RUPIA_FIRST, BROCK_DOC, RECEIPT_FIRST, RECEIPT_LAST, money, num, fdPct, outPct, votePct, vested, price, nbName, heDoc, FOUNDERS_AND, JGN_AND, listAnd, doc, EFF, DEF_ONLY, DEFINED, kv, tbl, coSig, personSig, memberSigs } = H;

const JGN_TITLE = 'JGN MEDIA LLC PLATFORM CONTRIBUTION, BRAND LICENSE, FUNDING AND ACCOUNT TRANSITION AGREEMENT';
const JGN_TITLE_TC = 'JGN Media LLC Platform Contribution, Brand License, Funding and Account Transition Agreement';
const COMPANY_CTRL = CO + ' or Company-controlled administration';

// 14 Historical Company Operating Expense and JGN Funding Advance Schedule
function doc14() {
  const body = EFF +
  `<p>This schedule documents the Company's historical operating expenses through the Actual Closing Date. Every one of them was funded by JGN Media LLC as a JGN Funding Advance under the JGN Agreement. No Founder paid any Company operating expense personally, and no part of any expense is credited as purchase price or as a Capital Contribution. This schedule reports the expense categories and the party that paid them; the amount of each category and the total are recorded in the JGN Funding Ledger kept under Section 7 of the JGN Agreement, a copy of which as of the Actual Closing Date is retained in the Company's record book with this schedule, and the JGN Funding Ledger controls the amounts.</p>` +
  tbl(['Expense category', 'What it was for', 'Paid by', 'When'], [
    ['Formation and registered agent', 'Delaware certificate of formation (filed ' + FORMED + ', file number ' + DEFILE + '), registered-agent service and state fees', 'JGN', 'August 2026 and renewals'],
    ['Hosting, deployment and infrastructure', 'Hosting and deployment of the app and the website, databases, authentication, object storage, transactional email, analytics and error monitoring', 'JGN', 'Through the Actual Closing Date'],
    ['Domains and DNS', 'Domain registrations and DNS for the Platform', 'JGN', 'Through the Actual Closing Date'],
    ['Sports data and odds', 'Scores, odds and sports-data API subscriptions used by the app and the data pipelines', 'JGN', 'Through the Actual Closing Date'],
    ['Software and developer tools', 'Development, design and AI tooling used to build and operate the Platform', 'JGN', 'Through the Actual Closing Date'],
    ['Subscription and community platforms', 'Subscription, payment and Discord-related platform fees for the Premium Offering', 'JGN', 'Through the Actual Closing Date'],
    ['Talent and contractors', 'Payments under the Talent Agreement from ' + TALENT_DATE + ' (Monthly Fee of $800 per month, view bonuses and revenue shares to the extent attributable to the Platform) and any other contractor payments for the Platform', 'JGN', 'From ' + TALENT_DATE],
    ['Professional and administrative', 'Accounting, tax, compliance and other administrative costs', 'JGN', 'Through the Actual Closing Date'],
  ]) +
  kv([['Total recorded Company operating expenses', 'Per the JGN Funding Ledger as of the Actual Closing Date'], ['Funded by JGN', 'All of them'], ['Funded by any Founder personally', 'None'], ['Treatment', 'JGN Funding Advances under Operating Agreement Sections 1.35 and 3.9 and Section 7 of the JGN Agreement: a Company obligation to JGN, without interest, repayable only after the Self-Sufficiency Date or at a Change of Control, and never collectible from any Member'], ['Purchase price or Capital Contribution', 'None of these expenses is purchase price, Unit consideration or a Capital Contribution for Units'], ['Member liability', 'None. No Cost-Share or reimbursement is owed by any Member'], ['Future funding', 'Governed by Section 7 of the JGN Agreement']]) +
  `<p>Historical operating expenses do not alter Founder ownership or vesting and are not offsets, reimbursements of purchase price, Unit consideration or Capital Contributions for Units. Any expense incurred for the Platform before the Company's formation on ${FORMED} was incurred for the Company's benefit and is recorded in the JGN Funding Ledger like every other item. Platform revenue, if any, collected through JGN-held accounts before the Actual Closing Date is recorded separately under Section 8 of the JGN Agreement and is not part of this expense schedule.</p>` + coSig();
  return doc(14, 'HISTORICAL COMPANY OPERATING EXPENSE AND JGN FUNDING ADVANCE SCHEDULE', body);
}

// 15 Company Asset Schedule
function doc15() {
  const body = DEF_ONLY +
  `<p>This schedule identifies Company asset categories for record-book purposes, and the JGN-owned assets the Company uses under license. Specific repository, account and subscriber records are maintained in the Company's systems and updated after material changes.</p>` +
  tbl(['Asset category', 'Description', 'Ownership/control status'], [
    ['Corporate records', 'Operating Agreement, consents, ledgers, schedules, Founder agreements, JGN Agreement, Talent Agreement, payment records, tax records and closing records.', 'Company'],
    ['Product and software', 'Source code, repositories, commits, branches, pull requests, issues, architecture, tests, integrations and deployment scripts of the Nosebleed Sports application, the website, the Discord bots and the data pipelines.', 'Company'],
    ['Data assets', 'Company-created schemas, databases, metadata, analytics, picks records and grading history, subscriber and member records, operational datasets, logs, derived insights and documentation, subject to privacy law, platform and data-provider terms and third-party rights.', 'Company'],
    ['Commercial assets', 'Subscriber relationships of the Premium Offering, Platform sponsorship and affiliate arrangements, pricing models, product specifications and contract templates.', 'Company'],
    ['Community', 'The Nosebleed Sports Discord server, its channels, roles, bots and member base.', 'Company'],
    ['Platform domains', 'Domains and DNS records used by the app and the website, transitioned to Company registrant control under the JGN Agreement; the Brand marks within them remain JGN property under the Brand License.', 'Company (registrant); Brand marks licensed from JGN'],
    ['Accounts and infrastructure', 'Company-critical accounts and production infrastructure identified in the Company Account Schedule.', 'Company-owned or Company-controlled as commercially practical'],
    ['Brand License', 'The exclusive, perpetual, royalty-free, transferable license to use the Nosebleed Sports brand in the Field defined in the JGN Agreement.', 'Company (licensee); JGN owns the Brand'],
    ['Promotion covenant', 'JGN\'s covenant to promote the Platform and the Premium Offering through the Social Accounts under the JGN Agreement.', 'Company (beneficiary)'],
    ['Talent Agreement rights', 'The Company\'s rights as a Company Party under the Talent Agreement, including Work Product relating to the Platform and the Premium Offering and the services of the Class B Member.', 'Company (shared with JGN as the Talent Agreement allocates)'],
    ['JGN retained assets', 'The Nosebleed Sports brand and marks; the Social Accounts and their audiences; historical content; sponsorship, advertising and affiliate relationships and revenue of the Social Accounts; the other media brands and accounts of JGN\'s network; and JGN\'s general business systems, contracts and media technology.', 'JGN Media LLC'],
  ], 'w3') + coSig();
  return doc(15, 'COMPANY ASSET SCHEDULE', body);
}

// 16 IP Assignment Schedule and Chain of Title Register
function doc16() {
  const body = DEF_ONLY +
  `<p>This register maps Platform-specific intellectual property and technology assets to the documents that establish Company ownership, license rights and chain of title. The Founder purchase price does not replace or reduce any IP assignment obligation.</p>` +
  tbl(['Asset or contributor category', 'Chain-of-title instrument', 'Company right'], [
    ['Founder-created Platform-specific work, before and after the Actual Closing Date', 'Founder PIIA (present assignment), supported by the Operating Agreement and the individual Founder Restricted Unit Purchase and Issuance Agreement ("RUPIA")', 'Present assignment to Company'],
    ['JGN-created, JGN-funded or JGN-controlled Platform-specific assets', JGN_TITLE_TC + ' (the "JGN Agreement"); JGN Member Consent Approving Nosebleed Agreement', 'Present assignment to Company'],
    ['JGN background technology embedded in Platform assets', 'JGN Agreement', 'Perpetual, irrevocable, worldwide, fully paid, royalty-free, transferable, sublicensable, acquisition-surviving license'],
    ['The Nosebleed Sports brand and marks', 'JGN Agreement (Brand License)', 'Exclusive in the Field, perpetual, royalty-free, transferable, sublicensable license; JGN retains ownership'],
    ['The Social Accounts and historical content', 'JGN Agreement (retained assets; promotion covenant)', 'Promotion of the Platform through the Social Accounts; no ownership'],
    ['Class B Member (Brock Smith) Work Product relating to the Platform and the Premium Offering', 'Talent Agreement Section 8.1 (present assignment); Work Product relating to the Brand and the Managed Accounts is assigned to JGN under the same Section', 'Present assignment to Company'],
    ['Other contractors or creators who worked on the Platform, its data pipelines or its content before the Actual Closing Date', 'Written IP assignment to the Company (or to JGN, assigned onward under the JGN Agreement); none is on file in this record book as of the Actual Closing Date, and the Chief Technology Officer shall obtain any that is needed', 'Assignment to Company once signed'],
    ['Future employees, contractors, consultants, developers and advisors', 'Company-approved PIIA, service-provider, contractor or developer agreement signed at engagement', 'Assignment or license upon signature'],
    ['Open-source, sports-data, odds and other third-party materials', 'Company records and third-party license and provider terms', 'Licensed rights only, subject to license and provider terms'],
    ['Company accounts and repositories', 'Operating Agreement, JGN Agreement, Company Account Schedule and access-control records', 'Company ownership or Company-controlled administration as commercially practical'],
  ]) +
  tbl(['Member', 'Assignment status', 'Related documents'], FOUNDERS.map(f => [nbName(f), 'Assigned to Company by execution of closing documents', 'Founder PIIA; RUPIA; Operating Agreement']).concat([[nbName(BROCK), 'Assigned under the Talent Agreement, effective on creation', 'Talent Agreement Section 8.1; Class B Unit Issuance Record']])) + coSig();
  return doc(16, 'IP ASSIGNMENT SCHEDULE AND CHAIN OF TITLE REGISTER', body);
}

// 17 Company Account Schedule
function doc17() {
  const cats = [
    'Source-code repositories for the app, the website, the Discord bots and the data pipelines',
    'Domains and domain registrars for the Platform',
    'DNS and content-delivery services',
    'Hosting and deployment platforms, object storage and production infrastructure',
    'Databases, authentication and user-management services',
    'Transactional email and messaging services',
    'Analytics, error-monitoring and logging services',
    'The Company\'s Discord server (server ownership, administrator roles, bots and role integrations)',
    'Subscription, payment and payout platforms for the Premium Offering',
    'App-store developer accounts, if and when the app is distributed through an app store',
    'Sports-data, scores and odds API accounts (account names and owners only; no credentials or keys)',
    'AI tool and developer tool accounts used for the Platform',
    'Password manager',
    'Google Workspace, email and shared drives used for Company work',
  ];
  const body = DEF_ONLY +
  `<p>An account in any category below is Company-critical if it is used for Company work or holds Company assets. Company-critical accounts shall belong to ${CO} or be under Company-controlled administration, and no Founder may permanently own a Company-critical account in a personal capacity. Control standard for every Company-critical account: multi-factor authentication, password-manager control, preserved audit history and, where practical, at least two Company-approved administrators. No credential, API key or recovery code is recorded in this schedule or anywhere in the record book, and no credential or API key is rotated, cancelled or regenerated except as the Chief Technology Officer approves.</p>` +
  tbl(['Account category', 'Required owner or controller'], cats.map(c => [c, COMPANY_CTRL]).concat([
    ['Company business checking account opened under the Banking Resolution (institution and last four digits recorded here when opened)', CO + ' (Company bank account)'],
    ['Other banking and finance systems', COMPANY_CTRL],
  ])) +
  `<p class="note">Social Accounts: the Nosebleed Sports TikTok and Instagram accounts and the other social media accounts of JGN's media network, including the accounts the Class B Member manages under the Talent Agreement, are owned by JGN Media LLC, are not Company Accounts and are not transitioned. The Company's interest in them is the promotion covenant in the JGN Agreement.</p>
<p class="note">Platform exception note: if a vendor does not permit legal transfer of an account, the responsible officer must document the exception and establish commercially equivalent Company control, export rights, administrative access and audit-history preservation where available. Accounts that JGN holds for the Company pending transition are recorded with their current controller and target date.</p>` + coSig();
  return doc(17, 'COMPANY ACCOUNT SCHEDULE', body);
}

// 18 Founder PIIA
function doc18() {
  const body = `<p>This Agreement (the "Founder PIIA") is entered into as of the Actual Closing Date by ${CO} and each Founder listed on the signature pages. ${DEFINED}</p>
<h2>1. PURPOSE</h2>
<p>This Agreement confirms each Founder's confidentiality, invention-assignment, data-security, account-control and acquisition-cooperation obligations. It supports the Company's IP chain of title and does not change ownership percentages, vesting, voting thresholds, distributions, officer titles or the purchase price for Units.</p>
<h2>2. COMPANY IP AND CONFIDENTIAL INFORMATION</h2>
<p>Company IP has the meaning given in the Operating Agreement, does not include an Excluded Project (Section 3), the Brand, the Social Accounts or JGN's retained assets, and includes all Platform-specific inventions, works of authorship, software, source code, repositories, commits, databases, schemas, data structures, data pipelines, odds and scores adapters, picks tracking and grading logic, Discord bots and automations, integrations, product designs, documentation, prompts, internal tooling, APIs, configurations, deployment pipelines, infrastructure, tests and related know-how.</p>
<p>Confidential Information has the meaning given in the Operating Agreement and includes all non-public Company information, including product plans, architecture, subscriber and member records, picks methodology and unpublished picks, pricing, contracts, sponsorship and data-provider terms, payment information, credentials, MFA, recovery methods, source code, databases, analytics, vendor terms, the terms of the Talent Agreement and the JGN Agreement, acquisition discussions and security materials.</p>
<h2>3. PRESENT ASSIGNMENT; EXCLUDED PROJECTS; CONNECTED PROJECTS</h2>
<p>Each Founder hereby assigns to the Company all right, title and interest worldwide in all Company IP (which does not include an Excluded Project) that the Founder owns or controls, whether created before or after the Actual Closing Date, including all copyrights, patent rights, trade secrets, database rights, mask works, moral rights to the extent assignable or waivable, rights of action, proceeds and recoveries. This assignment includes the work each Founder did on the app, the website and the Discord community before the Actual Closing Date, whether or not JGN funded it.</p>
<p>Anything created for the Company or in connection with the Company Business belongs exclusively to the Company, except an Excluded Project, work that the Talent Agreement or the JGN Agreement allocates to JGN, and work a Founder does after Continuous Service ends without using Company IP or Confidential Information. Ordinary work of a business that meets the conditions of Section 11.5(ii) or (iii) of the Operating Agreement, including work for JGN's retained media business and for TLNT Connect LLC, is not in connection with the Company Business unless it uses Company IP or Confidential Information. An "Excluded Project" is work, a project or a business that a Founder develops entirely on the Founder's own time, without using Company equipment, Company Accounts, Company Data, Company source code, Company IP or Confidential Information, that does not result from work the Founder performed for the Company, and that, when the Founder created or began it, was not a product or service of the same kind as either one the Company then offered or one then listed in Schedule F to the Operating Agreement as a Company product. An Excluded Project remains the Founder's property. A Founder is not required to disclose or list an Excluded Project unless it is also a Connected Project under the next paragraph, and the Company's later plans do not change its status. A Founder may put an Excluded Project on record by written notice to the Company through an Official Channel, in which case the project is treated for purposes of this Section as created or begun no later than the date of that notice. If part of an Excluded Project later uses Company resources of the kinds listed above or builds on Company IP, that part is Company IP and the rest of the project remains an Excluded Project. Information, accounts or materials that an outside project receives in an arm's-length dealing with the Company that was approved as the Operating Agreement requires, and uses only for that dealing, are not use of Company resources under this Section.</p>
<p>A Founder shall disclose to the Company in writing through an Official Channel each outside work, project or business of the Founder, and each position or interest of the Founder in another business, other than JGN and TLNT Connect LLC, that (a) uses Company equipment, Company Accounts, Company Data, Company source code, Company IP or Confidential Information, (b) receives money from, pays money to, or otherwise does business with the Company, or (c) is a Competing Business under Section 11.5 of the Operating Agreement or is, or includes, a product or service of the same kind as either one the Company offers or one listed in Schedule F to the Operating Agreement as a Company product, other than a business that meets the conditions of Section 11.5(ii) or (iii) of the Operating Agreement (a "Connected Project"). Disclosure is due within 30 days after the Actual Closing Date for a connection that exists on that date, and otherwise within 30 days after the connection first arises, and must describe the project and the connection in enough detail to identify them. Disclosure does not change who owns a Connected Project or any part of it; ownership is determined under this Section. Disclosure also does not by itself approve a Connected Project or any dealing between it and the Company; the Operating Agreement's Company Opportunity and competition rules (Sections 11.1 and 11.5) and its related-party approval requirements (Schedule B) apply. JGN's dealings with the Company are governed by the JGN Agreement and need no separate disclosure under this Section.</p>
<p>Materials unrelated to the Company and the Company Business remain owned by their proper owner, subject to the Operating Agreement, the JGN Agreement and any written license approved by the Company.</p>
<h2>4. SEPARATE ENFORCEABILITY</h2>
<p>Payment of the Founder purchase price for Class A Units does not reduce, waive, replace or satisfy the Founder's IP assignment, confidentiality, data-security, account-control, founder-duty, restrictive-covenant or acquisition-cooperation obligations. Founder IP assignments do not increase Unit allocations or change ownership percentages.</p>
<h2>5. PRIOR INVENTIONS AND JGN BOUNDARY</h2>
<p>No Founder excludes any Platform-specific work from this assignment. The Brand, the Social Accounts, JGN retained assets and JGN background technology are handled by the JGN Agreement. A Founder's work that is not Company IP, including an Excluded Project, may not be used in Company products without Company approval and, if required, a written license.</p>
<h2>6. CONFIDENTIALITY AND DATA USE</h2>
<p>Each Founder shall use Confidential Information only for Company purposes and shall protect it using commercially reasonable safeguards. Confidential Information, Company Data, subscriber and member records, unpublished picks and picks methodology, source code, prompts, payment information, security materials and acquisition-sensitive materials may not be used to train, fine-tune, evaluate or improve third-party AI models, external machine-learning systems or external analytics systems, or to operate any picks, content or community product outside the Company, without Company approval. This paragraph does not reach an Excluded Project, other property of the Founder, or JGN's retained media business.</p>
<p>Notice under 18 U.S.C. Section 1833(b): an individual will not be held criminally or civilly liable under any federal or state trade-secret law for disclosing a trade secret (a) in confidence to a federal, state or local government official, or to an attorney, solely for the purpose of reporting or investigating a suspected violation of law, or (b) in a complaint or other document filed under seal in a lawsuit or other proceeding. An individual who files a retaliation lawsuit for reporting a suspected violation of law may disclose the trade secret to the individual's attorney and use it in the court proceeding if the individual files any document containing the trade secret under seal and does not disclose it except under court order.</p>
<h2>7. COMPANY ACCOUNTS AND SECURITY</h2>
<p>Each Founder shall use Company-approved accounts, MFA, secure credentials, approved password-manager controls and least-privilege access for Company work. No Founder may withhold, delete, disable, conceal, lock out, hold hostage, impair or use Company Accounts, credentials, API keys, repositories, domains, logs, deployments, databases, the Discord server or vendor systems as leverage in any dispute, and no Founder may rotate, cancel or regenerate a credential or API key used by the Platform except as the Chief Technology Officer approves.</p>
<h2>8. RETURN, PRESERVATION AND ACQUISITION COOPERATION</h2>
<p>Upon Company request or departure, each Founder shall return, transfer or delete as directed all Company property, Company Data, Company Accounts, credentials, source code, repositories, prompts, subscriber materials, picks records, payment data, screenshots, backups, local clones and personal-drive copies, other than an Excluded Project or other property of the Founder. Each Founder shall reasonably cooperate in acquisition diligence, source-code review, IP confirmation, security review, privacy review, account transfer, disclosure schedules and closing.</p>
<h2>9. GENERAL</h2>
<p>This Agreement is governed by the laws of the State of Delaware without regard to conflict-of-laws rules, and disputes under it are subject to the forum provisions of Section 16.4 of the Operating Agreement. This Agreement may be signed in counterparts and by electronic signature, each of which is an original. If any provision is held unenforceable, it shall be reformed to the minimum extent necessary and the remainder enforced.</p>
<div class="sigpage"><h2>SIGNATURE PAGE</h2>` + coSig('Company') + FOUNDERS.map(f => personSig(f.name, 'Founder; Class A Member; ' + f.office)).join('') + `</div>`;
  return doc(18, 'FOUNDER PROPRIETARY INFORMATION, IP ASSIGNMENT AND DATA SECURITY AGREEMENT', body, { footTitle: 'FOUNDER PIIA' });
}

// 19 JGN Agreement
function doc19() {
  const body = `<p>This Agreement (the "JGN Agreement") is entered into as of the Actual Closing Date by and between ${CO} (the "Company") and JGN Media LLC, a New York limited liability company ("JGN"). ${DEFINED}</p>
<p>In consideration of the mutual covenants in this Agreement, the benefits to those of JGN's members who are Members of the Company, and other good and valuable consideration, the receipt and sufficiency of which are acknowledged, the parties intend to confirm the Company's ownership and control of the Platform and everything created specifically for it, to license the Nosebleed Sports brand to the Company and commit the audience of the Social Accounts to the Platform's growth, to record JGN's past funding of the Company and the terms of its continued funding, and to preserve JGN's ownership of the brand, the Social Accounts and its other media business.</p>
<h2>1. DEFINITIONS</h2>
<p>1.1 "Brand" means the "Nosebleed Sports" name, the Nosebleed Sports word marks and logos, the related names, logos, handles, trade dress and goodwill, and the names and marks of the Company's products that incorporate them (including "Nosebleed Live"), all owned by JGN.</p>
<p>1.2 "Social Accounts" means the Nosebleed Sports social media accounts on TikTok, Instagram, X, YouTube and every other platform, the other accounts of JGN's sports media network (including its sub-brand accounts), their followers and audiences, the content published on them, and the creator-program, monetization and advertising relationships attached to them, all owned by JGN. The Social Accounts include the Managed Accounts under the Talent Agreement.</p>
<p>1.3 "Platform Assets" means the Platform and all Platform-specific code, repositories, commits, branches, pull requests, issue histories, backends, APIs, database schemas and data, data pipelines, odds and scores adapters, picks records and grading logic, Discord server configuration, bots and role integrations, subscription and payment integrations, prompts and automations, internal tooling, documentation, configurations, deployment scripts, infrastructure, designs, product specifications, Platform domains, subscriber and member records of the Platform, and internal technical materials, in each case that JGN owns or controls, including everything the Founders built with JGN's funding.</p>
<p>1.4 "Field" means apps, websites, online and messaging communities (including Discord), subscription and membership products, paid picks, props, handicapping and analysis offerings, live sessions sold as part of them, and related digital products, tools and services offered to consumers under the Brand, together with sponsorship, advertising and affiliate placements within them.</p>
<p>1.5 "Reserved Field" means the Social Accounts, social, video and audio content published through them or through other media channels, newsletters and podcasts, free content and commentary of every kind, the sale of advertising, sponsorships, brand deals and affiliate placements on the Social Accounts and other media channels, merchandise, events not sold as part of the Premium Offering, and JGN's other media business, in each case under the Brand or otherwise.</p>
<p>1.6 "JGN Funding Advance" has the meaning given in the Operating Agreement; "JGN Funding Ledger" means the ledger JGN maintains under Section 7.1.</p>
<p>1.7 "Self-Sufficiency Date" means the first day after the Company has, for three consecutive calendar months, collected operating cash receipts into Company accounts that exceed its operating expenses for each of those months, and holds cash in Company accounts equal to at least three months of its then-budgeted operating expenses, as determined by the Chief Executive Officer and confirmed in writing by JGN, which confirmation JGN shall not unreasonably withhold.</p>
<h2>2. PRESENT ASSIGNMENT OF PLATFORM ASSETS</h2>
<p>JGN hereby assigns to the Company all right, title and interest worldwide in the Platform Assets. Ownership, payment or administration of a subscription, account, repository, tool or vendor relationship by JGN, and JGN's funding of the work, do not affect ownership of the Platform Assets, which belong to the Company. The assignment excludes the Brand, the Social Accounts and the other assets retained under Section 3, and it includes the Platform domains, whose registrant control is transitioned to the Company under Section 9 while the Brand marks within them remain JGN's and are licensed under Section 4.</p>
<h2>3. JGN RETAINED ASSETS</h2>
<p>JGN retains the Brand, the Social Accounts, the Reserved Field, all content published on the Social Accounts before and after the Actual Closing Date, its sponsorship, advertising, affiliate and creator-program relationships and revenue for the Social Accounts, its other media brands, accounts, customers, content and contracts, its general business systems, and background tools and technology not created specifically for the Platform.</p>
<h2>4. BRAND LICENSE</h2>
<p>4.1 Grant. JGN grants the Company an exclusive (including as against JGN), worldwide, perpetual, irrevocable except as Section 4.6 provides, fully paid, royalty-free license to use, reproduce, display and otherwise exploit the Brand in the Field, including in the names of the Company's products, in app stores, on the website and the Platform domains, in the Discord community, in the Premium Offering, and in the Company's advertising, marketing and promotion of the Field, with the right to sublicense to the Company's service providers, distributors, app stores and platform partners for those purposes (the "Brand License"). JGN reserves the Reserved Field and all uses of the Brand outside the Field. JGN shall not use, and shall not license or permit any other Person to use, the Brand or any confusingly similar name or mark in the Field.</p>
<p>4.2 Quality control. The Company shall use the Brand in the Field in a manner consistent with the quality, tone and reputation of the Nosebleed Sports media network, in compliance with applicable law and platform terms, and in accordance with reasonable written brand guidelines JGN provides from time to time that do not restrict the Company's products or pricing. On JGN's reasonable request, no more than twice a year, the Company shall provide representative samples of its use of the Brand. JGN may require correction of a use that materially departs from the guidelines, and the Company shall correct it within 30 days after written notice.</p>
<p>4.3 Ownership and goodwill. JGN owns the Brand, and all goodwill arising from the Company's use of the Brand inures to JGN. The Company shall not register, claim or challenge any right in the Brand or any confusingly similar name, mark, handle or domain, other than the Platform domains and app-store listings held as licensee under this Agreement, and shall cooperate with JGN's registration and enforcement of the Brand. JGN shall maintain its registrations and enforce the Brand against infringers in the Field at the Company's reasonable request, and, if JGN declines, the Company may enforce in its own name at its cost.</p>
<p>4.4 Transferability; Change of Control. The Brand License is an asset of the Company. It may be assigned by the Company, without JGN's consent, to a successor to the Company Business in a Change of Control or sale of substantially all of the Company's assets, and continues after that transaction on the same terms. JGN shall, within 10 business days after the Company's request in connection with a proposed Change of Control, deliver to the Company and the proposed acquirer a written confirmation that the Brand License is in effect, that no default exists (or stating any claimed default), and that the Brand License will continue in favor of the acquirer.</p>
<p>4.5 Sale of the Brand; first offer. Any sale, assignment or exclusive license of the Brand by JGN is subject to the Brand License, and JGN shall cause the transferee to assume this Section 4 in writing. Before JGN agrees to sell or assign the Brand to any Person other than an Affiliate that assumes this Agreement, JGN shall offer the Brand to the Company in writing on the price and terms JGN proposes, and the Company shall have 45 days to accept; if the Company declines or does not respond, JGN may sell on terms no more favorable to the buyer within 180 days.</p>
<p>4.6 Termination. The Brand License may be terminated by JGN only (a) if the Company ceases all use of the Brand in the Field for 24 consecutive months, or (b) on a final, non-appealable judgment that the Company materially breached Section 4.2 and failed to cure within 90 days after written notice. The Brand License does not terminate on the Company's insolvency, on a breach of any other agreement, on the end of JGN's funding commitment, on repayment of JGN Funding Advances, or on a change in the ownership of JGN or the Company. On any termination, the Company has 12 months to transition away from the Brand.</p>
<h2>5. PROMOTION COVENANT</h2>
<p>5.1 Promotion. For so long as the Brand License is in effect, JGN shall promote the Platform and the Premium Offering through the Social Accounts as the primary destination for the Nosebleed Sports audience, including by maintaining the Platform's link in the profiles of the Nosebleed Sports Social Accounts, publishing promotional posts, stories and live sessions on a regular cadence agreed between the Chief Executive Officer and JGN each quarter, and featuring the Platform in the Managed Accounts' content under the Talent Agreement. JGN shall not promote through the Social Accounts any product that is a Competing Business under Section 11.5 of the Operating Agreement.</p>
<p>5.2 Audience data. Follower and audience data of the Social Accounts belongs to JGN. JGN shall share with the Company the aggregate analytics reasonably needed to measure the promotion covenant and the Platform's funnel.</p>
<p>5.3 After a Change of Control. The promotion covenant continues for 24 months after the closing of a Change of Control on the terms then in effect, for the benefit of the successor to the Company Business, unless the successor and JGN agree otherwise in writing.</p>
<h2>6. TALENT AGREEMENT ALLOCATION</h2>
<p>As between the Company Parties under the Talent Agreement, JGN performs the obligations and holds the rights that relate to the Brand and the Managed Accounts, and the Company performs the obligations and holds the rights that relate to the Platform and the Premium Offering. Each Company Party honors the Contractor's equity in Section 5 of the Talent Agreement through Section 3.7 of the Operating Agreement. Payments JGN makes to the Contractor on the Company's behalf before the Self-Sufficiency Date are JGN Funding Advances. Brand Deal Revenue and Qualifying Revenue under the Talent Agreement are allocated between JGN and the Company under Section 8, and the Company Parties shall prepare the Contractor's monthly statement jointly.</p>
<h2>7. JGN FUNDING ADVANCES</h2>
<p>7.1 Historical advances; JGN Funding Ledger. JGN has funded every operating expense of the Company and the Platform through the Actual Closing Date, as recorded by category in Schedule C to the Operating Agreement and the Historical Company Operating Expense and JGN Funding Advance Schedule. JGN maintains a ledger of every JGN Funding Advance by date, payee, amount and category (the "JGN Funding Ledger"), delivers a copy to the Company at the Actual Closing Date for the record book and at least quarterly thereafter, and makes the supporting payment records available to any Member on request. The JGN Funding Ledger, as reconciled by the Company's Chief Technology Officer against those records, controls the amount of JGN Funding Advances.</p>
<p>7.2 Funding commitment. Until the Self-Sufficiency Date, JGN shall fund, as JGN Funding Advances, the Company's operating expenses incurred within the operating budget the Company approves under Section 4.3 of the Operating Agreement and JGN approves in writing each quarter, by depositing funds into the Company's bank account or paying vendors directly. JGN may decline to approve a budget or an item in it. JGN may end this commitment on 90 days' written notice to the Company approved by JGN's members, and the commitment ends automatically on the Self-Sufficiency Date and at the closing of a Change of Control. Funding that JGN provides after the commitment ends is also a JGN Funding Advance.</p>
<p>7.3 Repayment. JGN Funding Advances bear no interest. The Company repays them only (a) after the Self-Sufficiency Date, out of cash in excess of the reserves in Section 10.4 of the Operating Agreement, in amounts and on dates the Company approves under the Operating Agreement; (b) at the closing of a Change of Control or a sale of substantially all of the Company's assets, from the proceeds, before any distribution to the Members; and (c) on a dissolution of the Company, after creditors, from remaining assets. No Member is liable for any JGN Funding Advance, and JGN shall not seek payment from any Member. JGN may at any time forgive all or part of the JGN Funding Advances by written notice; a forgiven amount is cancelled and the parties treat it as their tax advisors direct.</p>
<p>7.4 No equity, security or control. JGN Funding Advances give JGN no Units, no right to convert into Units, no security interest, no lien, no vote and no right to control the Company. JGN's approval right under Section 7.2 is a funding decision only.</p>
<p>7.5 Subordination. JGN Funding Advances are subordinate in right of payment to any third-party indebtedness the Company incurs with Supermajority Approval, and JGN shall sign a customary subordination agreement a lender reasonably requests.</p>
<h2>8. REVENUE ALLOCATION</h2>
<p>Subscription, membership, premium-tool, Platform sponsorship, Platform affiliate and other revenue of the Field belongs to the Company. Advertising, sponsorship, brand-deal, affiliate, creator-program and monetization revenue of the Reserved Field belongs to JGN. Where a single arrangement spans both, the parties allocate it in good faith by the relative value of the Field and Reserved Field elements, as Section 4.2 of the Talent Agreement provides for the Contractor's share. Any Field revenue JGN collected into JGN-held accounts before the Actual Closing Date, or collects afterward pending transition of the collecting account, is held for the Company and, at the Company's election, remitted to the Company's bank account or credited against JGN Funding Advances, as recorded in the JGN Funding Ledger.</p>
<h2>9. COMPANY ACCOUNTS; CREDENTIALS; AUDIT HISTORY</h2>
<p>JGN shall preserve the Company's access to the Company Accounts, avoid unilateral lockout, transfer to the Company the ownership or administrative control of each Company Account that JGN holds (including the Platform domains, the Discord server, the repositories and the subscription and payment accounts) as commercially practical and in any event before the closing of a Change of Control, preserve commit history and audit logs where available, and maintain at least two Company-approved administrators for critical systems where practical. Credentials and API keys are transferred, and changed only as the Company's Chief Technology Officer approves; nothing in this Agreement requires or permits rotation, cancellation or regeneration of a credential or API key the Platform uses without that approval. The Company shall preserve JGN's access to the Social Accounts and shall not claim any right in them.</p>
<h2>10. NO EQUITY EFFECT</h2>
<p>This Agreement does not alter Founder Unit allocations, purchase prices, Capital Contributions, Capital Accounts, vesting, ownership percentages or governance rights. JGN is not a Member and receives no Units under this Agreement.</p>
<h2>11. JGN REPRESENTATIONS; FURTHER ASSURANCES</h2>
<p>JGN represents that it has full power and authority to enter into and perform this Agreement; that its members have approved this Agreement by the JGN Member Consent Approving Nosebleed Agreement (the "JGN Member Consent"); that it owns the Platform Assets and the Brand free of liens, licenses in the Field and other encumbrances, other than platform terms and the Talent Agreement; that it has not assigned, licensed or encumbered the Platform Assets or the Brand in the Field to any other Person; and that the JGN Funding Ledger is accurate in all material respects.</p>
<p>JGN shall sign documents and provide reasonable assistance requested to confirm, perfect, enforce or transfer the Company's rights, including in acquisition diligence, buyer questionnaires, source-code review, IP confirmation, Brand License confirmation under Section 4.4, account transfer, security review, privacy review, disclosure schedules and closing.</p>
<h2>12. COMPETITION</h2>
<p>During any period in which a member of JGN is within that member's Restricted Period under Section 11.5 of the Operating Agreement, JGN shall not, directly or indirectly, do anything that Section prohibits a Founder from doing, subject to the same exceptions, and shall not license the Brand or its background technology to, or promote through the Social Accounts, a Competing Business as defined in that Section. This does not restrict the Reserved Field, so long as that business is not itself a Competing Business and does not help build, run or scale one.</p>
<h2>13. GENERAL</h2>
<p>This Agreement is governed by the laws of the State of Delaware without regard to conflict-of-laws rules, and disputes under it are subject to the forum provisions of Section 16.4 of the Operating Agreement. The Company acts under this Agreement through its Chief Technology Officer or another officer who is not a member of JGN, as Section 8.2 of the Operating Agreement provides. This Agreement may be amended only by a writing signed by both parties and approved as a Major Decision under Schedule B to the Operating Agreement and by JGN's members. It may be signed in counterparts and by electronic signature, each of which is an original. If any provision is held unenforceable, it shall be reformed to the minimum extent necessary and the remainder enforced. Sections 2, 3, 4, 5.3, 7.3, 7.4, 8, 9, 10 and 11 survive any termination of JGN's funding commitment and any Change of Control.</p>
<div class="sigpage"><h2>SIGNATURE PAGE</h2>` +
  `<div class="sig"><p class="who">${CO}</p><p>By: _________________________________________</p><p>Name: ${CTO.name}</p><p>Title: ${CTO.office}, as the officer authorized by Resolution 10 of the Initial Member and Organizational Written Consent</p><p>Date signed: __________________________________</p></div>` +
  `<div class="sig"><p class="who">JGN Media LLC</p><p>By: _________________________________________</p><p>Name: ${CEO.name}</p><p>Title: Authorized Representative</p><p>Date signed: __________________________________</p></div></div>`;
  return doc(19, JGN_TITLE, body, { footTitle: 'JGN AGREEMENT', h1: JGN_TITLE });
}

// 20 JGN Member Consent
function doc20() {
  const body = `<p>The undersigned members of JGN Media LLC approve JGN's execution and performance of the JGN Media LLC Platform Contribution, Brand License, Funding and Account Transition Agreement with ${CO} (the "JGN Agreement"). This consent is effective upon signature; the JGN Agreement becomes effective as of the Actual Closing Date. Capitalized terms used but not defined in this consent have the meanings given in the Limited Liability Company Agreement of ${CO} (the "Nosebleed Operating Agreement") and in the JGN Agreement.</p>
<p>This approval includes the present assignment of the Platform Assets to ${CO}; the exclusive, perpetual, royalty-free, transferable Brand License in the Field; the promotion covenant; the allocation of the Talent Agreement between JGN and ${CO}; the recording of JGN's historical funding as JGN Funding Advances, repayable without interest only after the Self-Sufficiency Date or at a Change of Control and never by any member of ${CO}; JGN's funding commitment under Section 7.2 of the JGN Agreement, terminable on 90 days' notice approved by JGN's members; the revenue allocation; the account transition; and JGN's competition covenant in Section 12 of the JGN Agreement.</p>
<p>The undersigned authorize ${CEO.name} to execute the JGN Agreement on behalf of JGN Media LLC as Authorized Representative.</p>
<p>The undersigned are all of the members of JGN Media LLC and together hold one hundred percent (100%) of its membership interests, which meets every approval threshold under the JGN Media LLC operating agreement for each action approved in this consent.</p>
<p>The undersigned confirm that the Platform Assets and anything created specifically for the Platform belong exclusively to ${CO}; that the Brand, the Social Accounts and JGN's other assets remain the sole property of JGN Media LLC, subject to the Brand License and the promotion covenant; and that ownership or payment of subscriptions, accounts or work by JGN does not affect ownership of the Platform Assets.</p>
<p>The undersigned acknowledge that ${CO}'s Chief Technology Officer, ${CTO.name}, who is not a member of JGN, signs the JGN Agreement for ${CO} and acts for ${CO} in enforcing it.</p>
<p>This consent does not otherwise alter ${CO} Unit allocations, purchase prices, Capital Accounts, vesting or governance rights.</p>` +
  JGN_MEMBERS.map(f => personSig(f.name, 'Member of JGN Media LLC (25%)')).join('');
  return doc(20, 'JGN MEMBER CONSENT APPROVING NOSEBLEED AGREEMENT', body, { company: 'JGN MEDIA LLC', h1: 'JGN MEMBER CONSENT APPROVING NOSEBLEED AGREEMENT' });
}

// 21 Closing Checklist and Signature Index
function doc21() {
  const rupiaRange = `${RUPIA_FIRST} through ${RUPIA_FIRST + N_FOUNDERS - 1}`;
  const receiptRange = `${RECEIPT_FIRST} through ${RECEIPT_LAST}`;
  const steps = [
    ['1', 'Open the Company bank account under the Banking Resolution and record the institution and last four digits in the Company Account Schedule', 'Authorized Banking Officers (Chief Executive Officer; Chief Technology Officer)'],
    ['2', 'Deliver the JGN Funding Ledger and supporting records to all Members, and review the Historical Company Operating Expense and JGN Funding Advance Schedule', 'JGN; Company and Members'],
    ['3', 'Review the completed Factual Valuation Worksheet in the FMV Memorandum and confirm no contradictory valuation facts', 'Company and Members'],
    ['4', 'Approve FMV Memorandum', 'All Class A Members'],
    ['5', 'Execute Organizational Consent', 'All Class A Members'],
    ['6', 'Execute Operating Agreement', 'All Class A Members; the Company signs at step 17'],
    ['7', 'Execute Founder RUPIAs', 'Each Founder; the Company signs at step 17'],
    ['8', 'Execute Founder PIIA', 'Company and all Founders'],
    ['9', 'Execute JGN Member Consent', `All four JGN members (${JGN_MEMBERS.map(f => f.last).join(', ')})`],
    ['10', 'Execute JGN Agreement', `${CO} (Chief Technology Officer) and JGN Media LLC (Chief Executive Officer as Authorized Representative)`],
    ['11', 'Each Founder pays the purchase price into the Company bank account', 'Each Founder'],
    ['12', 'Confirm each Founder\'s payment against the bank records', 'Chief Technology Officer; Chief Executive Officer for the Chief Technology Officer\'s own payment'],
    ['13', 'Before the last payment is recorded, confirm that no later facts contradict the FMV Memorandum', 'Chief Executive Officer'],
    ['14', 'Record each Founder\'s payment', 'Company'],
    ['15', `Record payment dates and bank record references in documents 04 through 06, ${rupiaRange} and ${receiptRange}`, 'Company'],
    ['16', 'Issue Founder receipts once each payment is recorded', `Chief Executive Officer; Chief Technology Officer also on document ${RECEIPT_FIRST}`],
    ['17', `Record the Actual Closing Date on the Operating Agreement signature page, and sign the Company blocks on documents 01, 04 and ${rupiaRange}`, `Chief Executive Officer; Chief Technology Officer also on document ${RUPIA_FIRST}`],
    ['18', `Issue the Class B Units to Brock Smith, sign the Class B Unit Issuance Record (document ${BROCK_DOC}) and deliver to him a copy of the Operating Agreement and that record within 10 days`, 'Chief Executive Officer'],
    ['19', 'Update Founder Payment and Capital Contribution Ledger', 'Company'],
    ['20', 'Update Official Unit Ledger, including the Class B entry and the Reserved Units', 'Company'],
    ['21', 'Update Capitalization Table', 'Company'],
    ['22', 'Update Founder Equity and Vesting Ledger', 'Company'],
    ['23', 'Update Members\' Capital Accounts and accounting records, and record the JGN Funding Advances as a Company obligation on the terms of the JGN Agreement', 'Company'],
    ['24', 'Sign the Company signature blocks on the remaining record-book documents', 'Chief Executive Officer'],
    ['25', 'Sign Company Officer Certificate after all payments and issuances are complete', 'Chief Executive Officer; Chief Technology Officer for the payment confirmation'],
    ['26', 'Keep the executed record book, a copy of the Talent Agreement and the JGN Funding Ledger, and complete Company records', 'Company'],
  ];
  const body = EFF + `<h2>1. CLOSING CHECKLIST</h2>` +
  tbl(['Step', 'Document or action', 'Responsible signer', 'Date completed'], steps.map(s => [s[0], s[1], s[2], ''])) +
  `<h2>2. SIGNATURE INDEX</h2>` +
  tbl(['Signer', 'Capacity', 'Documents requiring signature'], [
    [nbName(CEO), 'Class A Member; CEO; Company authorized signer; JGN member; JGN Authorized Representative', `Operating Agreement, Organizational Consent, FMV Memorandum, Founder PIIA, RUPIA (document ${RUPIA_FIRST}), JGN Member Consent, JGN Agreement on behalf of JGN Media LLC, the Company signature block in documents 00, 01, 04 through 18, 21 through 24, ${RUPIA_FIRST + 1} through ${BROCK_DOC} and ${RECEIPT_FIRST + 1} through ${RECEIPT_LAST}, receipt acknowledgment (document ${RECEIPT_FIRST}) if requested`],
    [nbName(CTO), 'Class A Member; CTO; Company signer for the JGN Agreement', `Operating Agreement, Organizational Consent, FMV Memorandum, Founder PIIA, RUPIA (document ${RUPIA_FIRST + 1}), JGN Agreement on behalf of the Company (document 19), Company countersignature on documents ${RUPIA_FIRST} and ${RECEIPT_FIRST}, payment confirmation on document 07, receipt acknowledgment (document ${RECEIPT_FIRST + 1}) if requested`],
  ].concat(FOUNDERS.slice(2).map((f, i) => [nbName(f), `Class A Member; ${f.short}; JGN member`, `Operating Agreement, Organizational Consent, FMV Memorandum, Founder PIIA, RUPIA (document ${RUPIA_FIRST + 2 + i}), JGN Member Consent, receipt acknowledgment (document ${RECEIPT_FIRST + 2 + i}) if requested`]))
  .concat([[nbName(BROCK), 'Class B Member', `None. Brock Smith signs nothing at closing; he is admitted on issuance under Operating Agreement Section 3.7 and receives a copy of the Operating Agreement and document ${BROCK_DOC}. He may sign the Schedule E joinder at his election.`],
           ['JGN Media LLC', `Contracting entity; ${CEO.name} as Authorized Representative`, 'JGN Agreement']])) +
  `<p class="note">RUPIA means Restricted Unit Purchase and Issuance Agreement. FMV Memorandum means the Founder Equity Fair Market Value Determination Memorandum. Organizational Consent means the Initial Member and Organizational Written Consent. Founder PIIA means the Founder Proprietary Information, IP Assignment and Data Security Agreement. JGN Agreement means the JGN Media LLC Platform Contribution, Brand License, Funding and Account Transition Agreement. JGN Member Consent means the JGN Member Consent Approving Nosebleed Agreement. The Chief Technology Officer countersigns the Chief Executive Officer's RUPIA and receipt for the Company and signs the JGN Agreement for the Company because he holds no interest in JGN.</p>` + coSig();
  return doc(21, 'CLOSING CHECKLIST AND SIGNATURE INDEX', body);
}

// 22 Organization and Governance Summary
function doc22() {
  const body = DEF_ONLY +
  `<p>The Company is a Delaware member-managed limited liability company. There is no separate manager body. Class A Members approve Major Decisions and officers operate inside delegated lanes and authority thresholds. The Class B Member holds a non-voting economic interest.</p>` +
  kv([['Legal name', CO], ['Formed', 'Delaware, ' + FORMED], ['Delaware file number', DEFILE], ['EIN', EIN], ['Registered agent', RA], ['Principal business office', ADDR], ['Authorized Units', num(AUTH_UNITS) + ' (' + num(CLASS_A) + ' Class A and ' + num(CLASS_B) + ' Class B issued; ' + num(RESERVE) + ' reserved)']]) +
  tbl(['Layer', 'Persons', 'Authority'], [
    ['Class A Members', FOUNDERS_AND, 'Ownership, voting, Major Decisions, amendments, Change of Control, governance review and other Member approvals under the Operating Agreement, including the meeting, participation and responsiveness standards in Section 4.5. Every approval requires 75% of outstanding Class A Units.'],
    ['Class B Member', BROCK.name, 'Non-voting economic interest (profits interest) issued under the Talent Agreement; bound by the Operating Agreement without signing it; services and compensation governed by the Talent Agreement.'],
    ['Chief Executive Officer', CEO.name, 'Executive leadership, Company signatures and ordinary-course authority inside approved thresholds; Tax Representative; Authorized Banking Officer.'],
    ['Chief Technology Officer', CTO.name, 'Platform engineering and delivery, ordinary-course authority inside approved thresholds; Authorized Banking Officer; confirms Founder payments; signs and enforces the JGN Agreement for the Company as the officer with no JGN interest.'],
    ['Other officers', FOUNDERS.slice(2).map(f => `${f.name} (${f.office})`).join(', '), 'Officer-lane authority inside approved thresholds.'],
    ['JGN Media LLC', 'Separate entity owned 25% each by ' + JGN_AND, 'Owns the Nosebleed Sports brand and the Social Accounts; licenses the brand to the Company and promotes the Platform under the JGN Agreement; assigned the Platform Assets to the Company; funds the Company until the Self-Sufficiency Date through JGN Funding Advances; ' + CEO.name + ' signs the JGN Agreement as Authorized Representative.'],
    ['Reserved Units', num(RESERVE) + ' Units (' + fdPct(RESERVE) + ' fully diluted)', 'Unissued; reserved for future strategic partners and Milestone Units; issuable only as a Major Decision (strategic partners) or when earned (Milestone Units).'],
  ], 'w') + coSig();
  return doc(22, 'ORGANIZATION AND GOVERNANCE SUMMARY', body);
}

// 23 Capitalization Reconciliation Report
function doc23() {
  const per = FOUNDERS.map(f => `<h3>${f.name}</h3>` + kv([['Units', num(f.units) + ' Class A Units'], ['Percentage Interest', outPct(f.units)], ['Voting Interest', votePct(f.units)], ['Fully Diluted Percentage', fdPct(f.units)], ['Per-Unit FMV', '$0.001'], ['Purchase Price', price(f)], ['Initial Capital Contribution (cash)', price(f)], ['Capital Account Credit', price(f)], ['Immediately Vested', num(vested(f))], ['Restricted', num(vested(f))], ['Original Cost', '$0.001 per Unit']], 'kv2')).join('');
  const brock = `<h3>${BROCK.name}</h3>` + kv([['Units', num(CLASS_B) + ' Class B Units'], ['Percentage Interest', outPct(CLASS_B)], ['Voting Interest', 'None'], ['Fully Diluted Percentage', fdPct(CLASS_B)], ['Threshold Amount', money(THRESHOLD)], ['Purchase Price', 'None'], ['Initial Capital Contribution', 'None'], ['Capital Account Credit', '$0'], ['Vesting', 'Per Talent Agreement Section 5.4'], ['Original Cost', 'Zero']], 'kv2');
  const body = EFF + per + brock +
  tbl(['Item', 'Total'], [['Authorized Units', num(AUTH_UNITS)], ['Issued Class A Units', num(CLASS_A)], ['Issued Class B Units', num(CLASS_B)], ['Outstanding Units', num(OUTSTANDING)], ['Reserved Units (unissued)', num(RESERVE)], ['Total Percentage Interests', '100%'], ['Total Voting Interests', '100%'], ['Total Fully Diluted Percentages (including Reserved Units)', '100%'], ['Aggregate purchase price', money(A_TOTAL_PRICE)], ['Aggregate initial Capital Contributions (cash)', money(A_TOTAL_PRICE)], ['Aggregate capital credited to Members\' Capital Accounts', money(A_TOTAL_PRICE)], ['FMV per Class A Unit', '$0.001'], ['Total company equity FMV', money(FMV_TOTAL)], ['Class B Threshold Amount', money(THRESHOLD)], ['Immediately vested Class A Units', num(CLASS_A / 2)], ['Restricted Class A Units over 48 months', num(CLASS_A / 2)], ['Monthly vesting', '1/48 of each Founder\'s restricted Units monthly, with final installment true-up under Operating Agreement Section 6.2.']]) +
  `<p>Every Founder purchase price equals Class A Units multiplied by $0.001 exactly (${FOUNDERS.map(f => num(f.units) + ' × $0.001 = ' + price(f)).join('; ')}); aggregate purchase price, aggregate initial Capital Contributions and aggregate capital credited to Members' Capital Accounts reconcile exactly at ${money(A_TOTAL_PRICE)}; issued Class A Units (${num(CLASS_A)}) plus issued Class B Units (${num(CLASS_B)}) plus Reserved Units (${num(RESERVE)}) equal exactly ${num(AUTH_UNITS)} authorized Units; Percentage Interests total exactly 100% of the ${num(OUTSTANDING)} outstanding Units; and Voting Interests total exactly 100% of the ${num(CLASS_A)} outstanding Class A Units.</p>` + coSig();
  return doc(23, 'CAPITALIZATION RECONCILIATION REPORT', body);
}

// 24 Record Book Certification
function doc24() {
  const body = EFF +
  tbl(['Area', 'Record'], [
    ['Capitalization', `This record book documents ${num(AUTH_UNITS)} authorized Units; ${num(CLASS_A)} Class A Units issued to five Founders (${FOUNDERS.map(f => fdPct(f.units)).join(' / ')} fully diluted); ${num(CLASS_B)} Class B Units (${fdPct(CLASS_B)} fully diluted) issued to Brock Smith; ${num(RESERVE)} Reserved Units (${fdPct(RESERVE)}) unissued; ${money(FMV_TOTAL)} total equity FMV; $0.001 per Class A Unit; and a Class B Threshold Amount of ${money(THRESHOLD)}.`],
    ['Founder purchase structure', 'Each Founder\'s purchase price is paid in cash into the Company bank account, confirmed against the bank records. It is separate from services, IP, JGN Funding Advances, reimbursements, notes and deferred-payment rights.'],
    ['Class B issuance', 'Brock Smith\'s Class B Units are issued as profits interests under the Talent Agreement and Operating Agreement Section 3.7, without a purchase price and without his signature; Milestone Units, if earned, are issued from the Reserved Units.'],
    ['Historical expenses and funding', 'Every historical operating expense was funded by JGN Media LLC as a JGN Funding Advance, repayable by the Company without interest only after the Self-Sufficiency Date or at a Change of Control and never by any Member, as documented in the Historical Company Operating Expense and JGN Funding Advance Schedule, Schedule C to the Operating Agreement and the JGN Funding Ledger.'],
    ['Company identifiers', `Formation date ${FORMED}, Delaware file number ${DEFILE}, EIN ${EIN}, registered agent and principal business office are recorded in the Operating Agreement and the record book.`],
    ['Bank accounts', 'The Company bank account is opened under the Banking Resolution before the Actual Closing Date and recorded in the Company Account Schedule.'],
    ['Governance', 'Member-managed Delaware LLC structure, officer lanes, a uniform 75% Class A approval threshold under which silence never counts as approval (Operating Agreement Sections 5.2 and 5.3), Member meeting and participation standards (Operating Agreement Section 4.5), vesting, transfer restrictions, repurchase terms, the Reserved Units and JGN\'s ownership are documented.'],
    ['Brand and audience', 'The Nosebleed Sports brand and the Social Accounts are owned by JGN Media LLC; the Company holds the exclusive, perpetual, royalty-free, transferable Brand License in the Field and the benefit of the promotion covenant under the JGN Agreement.'],
    ['IP chain of title', 'Founder PIIA, JGN Agreement, JGN Member Consent, Talent Agreement, IP Assignment Schedule and Chain of Title Register, Company Account Schedule and acquisition-cooperation obligations are included in or referenced by this record book.'],
    ['JGN authority', `${CEO.name} is identified as JGN Media LLC Authorized Representative for JGN's entity-level signature; all four JGN members, holding 100% of JGN's membership interests, approve the JGN Agreement in the JGN Member Consent; ${CTO.name}, who holds no JGN interest, signs the JGN Agreement for the Company.`],
    ['Tax responsibility', 'Each Member bears responsibility for that Member\'s own tax position with respect to the Units; the Company provides no tax advice.'],
  ], 'w') +
  `<p>This certification records what this record book contains. It is not a legal opinion, tax opinion, valuation opinion, fairness opinion or audit opinion.</p>` + coSig();
  return doc(24, 'RECORD BOOK CERTIFICATION', body);
}

module.exports = { doc14, doc15, doc16, doc17, doc18, doc19, doc20, doc21, doc22, doc23, doc24 };
